INSERT INTO `LNM_evaluation_type` VALUES (5,'Echelle de notation ABCDE simple','A','E','C','{E,D,C,B,A}','{Non évaluable; N\'atteint pas le minimum requis; Minimum requis atteint avec des lacunes importantes ne remettant pas en cause la compréhension du sujet; Bonne maitrise du sujet avec des lacunes mineures à combler; Excellente maitrise du sujet, quelques lacunes négligeables nécessitant des approfondissements acceptables ');
